/*
  Black Sun Archive — Chernobog
  =================================
  Navigation SPA :
  - le menu de gauche ne recharge pas la page ;
  - seule l'image de droite change ;
  - le lecteur audio reste actif ;
  - les boutons [+] ouvrent une fiche d'archive.
*/

const rightPageImage = document.getElementById("right-page-image");
const links = document.querySelectorAll("[data-page]");

/*
  Pages actuellement intégrées dans le HTML/JS.
  Plus tard, tu pourras remplacer les data:image par des chemins comme :
  "images/pages/personnalite.webp"
*/
const pageImages = {'index': 'data:image/png;base64,', 'identite': 'data:image/svg+xml;base64,', 'apparence': 'data:image/svg+xml;base64,', 'personnalite': 'data:image/png;base64,', 'pouvoirs': 'data:image/svg+xml;base64,', 'histoire': 'data:image/svg+xml;base64,', 'origine-du-nom': 'data:image/svg+xml;base64,', 'relations': 'data:image/svg+xml;base64,'};

function setActiveMenu(pageId) {
  links.forEach(link => {
    link.classList.toggle("active", link.dataset.page === pageId);
  });
}

function setPersonalityMode(pageId) {
  document.body.classList.toggle("personnalite-active", pageId === "personnalite");
}

function changeRightImage(pageId) {
  if (!rightPageImage || !pageImages[pageId]) return;

  if (rightPageImage.src === pageImages[pageId]) return;

  rightPageImage.classList.add("is-changing");

  setTimeout(() => {
    rightPageImage.src = pageImages[pageId];

    rightPageImage.onload = () => {
      rightPageImage.classList.remove("is-changing");
    };

    // Sécurité si l'événement onload ne se déclenche pas.
    setTimeout(() => rightPageImage.classList.remove("is-changing"), 520);
  }, 160);
}

function showPage(pageId) {
  if (!pageImages[pageId]) pageId = "index";

  setActiveMenu(pageId);
  setPersonalityMode(pageId);
  changeRightImage(pageId);

  history.pushState(null, "", "#" + pageId);
}

links.forEach(link => {
  link.addEventListener("click", event => {
    event.preventDefault();
    showPage(link.dataset.page);
  });
});

window.addEventListener("popstate", () => {
  showPage(location.hash.replace("#", "") || "index");
});

showPage(location.hash.replace("#", "") || "index");


// =====================================================
// Fiche d'archive — boutons [+] de la page Personnalité
// =====================================================

const archiveSheet = document.getElementById("archiveSheet");
const archiveTitle = document.getElementById("archiveTitle");
const archiveText = document.getElementById("archiveText");

document.querySelectorAll(".archive-plus").forEach(button => {
  button.addEventListener("click", () => {
    archiveTitle.textContent = button.dataset.archiveTitle;
    archiveText.textContent = button.dataset.archiveText;
    archiveSheet.classList.add("open");
  });
});

document.querySelector(".archive-close")?.addEventListener("click", () => {
  archiveSheet.classList.remove("open");
});

document.addEventListener("keydown", event => {
  if (event.key === "Escape") {
    archiveSheet?.classList.remove("open");
  }
});
